class Score:
    def __init__(self,value):
        self.value = value
    def __repr__(self):
        return f"Score({self.value})"
    def __str__(self):
        return f"{self.value} points"
score = Score(4)
print(repr(score))
print(score)

class Battery:
    def __init__(self):
        self.charge = 3
    def use(self):
        if self.charge < 1:
            return False
        self.charge -= 1
        return True
battery = Battery()
print(battery.use(),battery.charge)
